@Component("wishlist-entity-projector")
public class WishlistEntityProjector implements EntityProjector<Wishlist>{
		
	// core constructor
	public WishlistEntityProjector(ProjectorRegistry registry,
										WishlistRepository repository ) {
        this.registry 	= registry;
		this.repository = repository;
    }

	@Override
	public Class<Wishlist> getEntityClass() {
		return Wishlist.class;
	}

    /*
	 * Insert a Wishlist
	 * 
     * @param	entity Wishlist
     */
    public Wishlist create( Wishlist entity) {
	    LOGGER.info("creating " + entity.toString() );
	   
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    return repository.save(entity);
        
    }

	/*
	 * Update a Wishlist
	 * 
     * @param	entity Wishlist
     */
    public Wishlist update( Wishlist entity) {
	    LOGGER.info("updating " + entity.toString() );

	    // ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		return repository.save(entity);

    }
    
	/*
	 * Delete a Wishlist
	 * 
     * @param	id		UUID
     */
    public Wishlist delete( UUID id ) {
	    LOGGER.info("deleting " + id.toString() );

    	// ------------------------------------------
    	// locate the entity by the provided id
    	// ------------------------------------------
	    Wishlist entity = repository.findById(id).get();
	    
    	// ------------------------------------------
    	// delete what is discovered 
    	// ------------------------------------------
    	repository.delete( entity );
    	
    	return entity;
    }    

    /*
     * Assign a Customer
     * 
     * @param	parentId	UUID
     * @param	assignment 	Customer 
     * @return	Wishlist
     */
    public Wishlist assignCustomer( UUID parentId, Customer assignment ) {
	    LOGGER.info("assigning Customer as " + assignment.toString() );

	    Wishlist parentEntity = repository.findById( parentId ).get();
	    assignment = registry.project( Customer.class, assignment.getCustomerId());

	    // ------------------------------------------
		// assign the Customer to the parent entity
		// ------------------------------------------ 
	    parentEntity.setCustomer( assignment );

	    // ------------------------------------------
    	// save the parent entity
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

	/*
	 * Unassign the Customer
	 * 
	 * @param	parentId		UUID
	 * @return	Wishlist
	 */
	public Wishlist unAssignCustomer( UUID parentId ) {
		Wishlist parentEntity = repository.findById(parentId).get();

		LOGGER.info("unAssigning Customer on " + parentEntity.toString() );
		
	    // ------------------------------------------
		// null out the Customer on the parent entithy
		// ------------------------------------------     
	    parentEntity.setCustomer(null);

	    // ------------------------------------------
		// save the parent entity
		// ------------------------------------------ 
	    repository.save(parentEntity);
    
	    return parentEntity;
	}


    /*
     * Add to the Items
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	Wishlist
     */
    public Wishlist addToItems( UUID parentId, WishlistItem addTo ) {
	    LOGGER.info("handling AssignItemsToWishlistEvent - " );
	    
	    Wishlist parentEntity = repository.findById(parentId).get();
	    WishlistItem child = registry.project( WishlistItem.class, addTo.getWishlistItemId());
	    
	    parentEntity.getItems().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the Items
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	Wishlist
     */
	public Wishlist removeFromItems( UUID parentId, WishlistItem removeFrom ) {
	    LOGGER.info("handling RemoveItemsFromWishlistEvent " );
	
	    Wishlist parentEntity = repository.findById(parentId).get();
	    WishlistItem child = registry.project( WishlistItem.class, removeFrom.getWishlistItemId());
	    
	    parentEntity.getItems().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}



    /**
     * Method to retrieve the Wishlist via an FindWishlistQuery
     * @return 	query	FindWishlistQuery
     */
    @SuppressWarnings("unused")
    public Wishlist find( UUID id ) {
    	LOGGER.info("handling find using " + id.toString() );
    	try {
    		return repository.findById(id).get();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find a Wishlist - {0}", exc.getMessage() );
    	}
    	return null;
    }
    
    /**
     * Method to retrieve a collection of all Wishlists
     *
     * @param	query	FindAllWishlistQuery 
     * @return 	List<Wishlist> 
     */
    @SuppressWarnings("unused")
    public List<Wishlist> findAll( FindAllWishlistQuery query ) {
    	LOGGER.info("handling findAll using " + query.toString() );
    	try {
    		return repository.findAll();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find all Wishlist - {0}", exc.getMessage() );
    	}
    	return null;
    }


    //--------------------------------------------------
    // attributes
    // --------------------------------------------------
	@Autowired
    protected final WishlistRepository repository;
	protected final ProjectorRegistry registry;


    private static final Logger LOGGER 	= LoggerFactory.getLogger(WishlistEntityProjector.class.getName());

}
